    SpellID = {label = "Learned Spell", tooltip = "Spell taught along with entry. Talent spells are rejected.", type = "int", ref = "spell"},
    entry = {label = "Spell", tooltip = "Spell that, once known, also teaches SpellID. Unlearning it removes SpellID too.", type = "int", ref = "spell"},
}

GameEditorData.Fields.spell_linked_spell = {
    comment = {label = "Comment", tooltip = "Free text note. The server does not read it.", type = "string"},
    spell_effect = {label = "Linked Spell", tooltip = "Positive casts or applies this spell. Negative removes that aura, or for type 2 grants immunity to it while the trigger aura is up.", type = "int", ref = "spell"},
    spell_trigger = {label = "Trigger Spell", tooltip = "Spell that fires the link. Negative means when its aura is removed, which only works with type 0.", type = "int", ref = "spell"},
    type = {label = "Type", tooltip = "0 after the cast (or on aura removal if trigger is negative). 1 on each target hit. 2 while the trigger aura is applied, removed with it.", type = "int", enum = "SpellLinkedType"},
}

GameEditorData.Fields.spell_pet_auras = {
    aura = {label = "Pet Aura", tooltip = "Spell cast on the pet as a fully triggered aura.", type = "int", ref = "spell"},
    effectId = {label = "Effect", tooltip = "Effect of the owner spell that holds the link. Must be a dummy effect or a dummy aura.", type = "int", enum = "SpellEffectIndex"},
    pet = {label = "Pet Entry", tooltip = "creature_template entry of the pet. 0 is used for every pet that has no row of its own.", type = "int", ref = "creature"},
    spell = {label = "Owner Spell", tooltip = "Spell on the owner that grants the pet aura while active.", type = "int", ref = "spell"},
}

GameEditorData.Fields.spell_proc = {
    AttributesMask = {label = "Attributes", tooltip = "Extra proc rules, see the flags.", type = "int", flags = "ProcAttributes"},
    Chance = {label = "Chance", tooltip = "Proc chance in percent. When both this and PPM are 0 the Spell.dbc procChance is used.", type = "float"},
    Charges = {label = "Charges", tooltip = "Procs before the aura drops. 0 keeps the Spell.dbc procCharges.", type = "int"},
    Cooldown = {label = "Cooldown (ms)", tooltip = "Milliseconds before the aura can proc again. Applies to the whole aura.", type = "int"},
