    ProcFlags = {label = "Proc Flags", tooltip = "Events that can proc the aura. 0 keeps the procFlags from Spell.dbc.", type = "int", flags = "ProcFlags"},
    ProcsPerMinute = {label = "Procs Per Minute", tooltip = "When set and the event has damage info, chance comes from this and the caster's weapon speed.", type = "float"},
    SchoolMask = {label = "School Mask", tooltip = "Only events of these schools can proc. 0 means any school.", type = "int", flags = "SpellSchoolMask"},
    SpellFamilyMask0 = {label = "Family Mask 0", tooltip = "SpellFamilyFlags bits, word 0. With all three at 0 any spell of the family matches. SpellClassMaskExtension entries also count.", type = "int", classMask = {family = "SpellFamilyName", word = 0}},
    SpellFamilyMask1 = {label = "Family Mask 1", tooltip = "SpellFamilyFlags bits, word 1.", type = "int", classMask = {family = "SpellFamilyName", word = 1}},
    SpellFamilyMask2 = {label = "Family Mask 2", tooltip = "SpellFamilyFlags bits, word 2.", type = "int", classMask = {family = "SpellFamilyName", word = 2}},
    SpellFamilyName = {label = "Spell Family", tooltip = "Only spells of this family can proc. 0 means any spell and the family masks are then ignored.", type = "int", enum = "SpellFamily"},
    SpellId = {label = "Spell", tooltip = "Aura spell the proc rules are for. Negative applies to all ranks and must be the first rank.", type = "int", ref = "spell"},
    SpellPhaseMask = {label = "Spell Phase", tooltip = "Cast, hit or finish phase. Required for done spell proc flags, with 0 those never proc.", type = "int", flags = "ProcSpellPhaseMask"},
    SpellTypeMask = {label = "Spell Type", tooltip = "Damage, heal or other spells only. 0 means any. Only checked for spell proc flags.", type = "int", flags = "ProcSpellTypeMask"},
}

GameEditorData.Fields.spell_ranks = {
