    rank = {label = "Rank", tooltip = "Rank number, 1 to n with no gaps. A bad sequence drops the whole chain.", type = "int"},
    spell_id = {label = "Spell", tooltip = "Spell at this rank of the chain.", type = "int", ref = "spell"},
}

GameEditorData.Fields.spell_required = {
